<?php require 'config.php'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$email=trim($_POST['email']);$pw=$_POST['password']; if($name && filter_var($email,FILTER_VALIDATE_EMAIL) && strlen($pw)>=6){try{$s=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);header('Location: login.php');exit;}catch(PDOException $e){$err='Email already registered.';}}else{$err='Enter valid details; password must be at least 6 characters.';}} ?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"><title>Register</title></head><body><div class="wrap"><div class="card"><h1>Create account</h1><p><?=h($err)?></p><form method="post"><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" minlength="6" required><button>Register</button></form><p><a href="login.php">Already registered? Login</a></p></div></div></body></html>